#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/control/shared_capabilities/shared_capabilities.hpp"
#include "gui_forms/image_list.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// TreeListView's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/tree_list_view.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// Width of one tree level, in logical units; the tree column's text starts after the indentation, the expander and the icon.
template <typename Declaring>
struct TreeListViewIndentationCapability {
    PropertyCell<double, TreeListViewIndentationCapability<Declaring>> indentation{18.0};

    static void assign(TreeListViewIndentationCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.indentation), incoming);
        if (!capability.indentation.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.indentation));
    }
};

// The images that the nodes' image_key values name; a list must be alive and belong to this view's Window.
template <typename Declaring>
struct TreeListViewImageListCapability {
    PropertyCell<std::shared_ptr<ImageList>, TreeListViewImageListCapability<Declaring>> image_list{};

    static void assign(TreeListViewImageListCapability& capability, std::shared_ptr<ImageList> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.image_list), incoming);
        if (!capability.image_list.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.image_list));
    }
};

// The selected node's stable ID, or none.
template <typename Declaring>
struct TreeListViewSelectedIdCapability {
    PropertyView<std::optional<std::string>, TreeListViewSelectedIdCapability<Declaring>> selected_id;

    static void assign(TreeListViewSelectedIdCapability& capability, std::optional<std::string> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.selected_id), std::move(incoming));
    }

    static std::optional<std::string> read(const TreeListViewSelectedIdCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::optional<std::string> current = control.read_view(capability.selected_id);
        return current;
    }
};

// Every TreeListView capability, in the order the declaring class takes them.
template <typename Declaring>
struct TreeListViewCapabilities : public TreeListViewIndentationCapability<Declaring>,
                                  public TreeListViewImageListCapability<Declaring>,
                                  public FontCapability<Declaring>,
                                  public TreeListViewSelectedIdCapability<Declaring> {
    TreeListViewCapabilities() : FontCapability<Declaring>(FontSpec{FontRole::content, 10.5, 400, false}) {}
};

} // namespace gui_forms
